DROP INDEX IF EXISTS idx_menu_pizzeria_id;
DROP INDEX IF EXISTS idx_person_order_person_id;
DROP INDEX IF EXISTS idx_person_order_menu_id;
DROP INDEX IF EXISTS idx_person_visits_person_id;
DROP INDEX IF EXISTS idx_person_visits_pizzeria_id;

CREATE INDEX idx_menu_pizzeria_id ON menu(pizzeria_id);

CREATE INDEX idx_person_order_person_id ON person_order(person_id);
CREATE INDEX idx_person_order_menu_id ON person_order(menu_id);

CREATE INDEX idx_person_visits_person_id ON person_visits(person_id);
CREATE INDEX idx_person_visits_pizzeria_id ON person_visits(pizzeria_id);

SET enable_seqscan = off;

EXPLAIN ANALYZE
SELECT m.pizza_name, pz.name AS pizzeria_name
FROM menu m
JOIN pizzeria pz ON m.pizzeria_id = pz.id;

DROP INDEX IF EXISTS idx_person_name;
CREATE INDEX idx_person_name ON person(UPPER(name));

SET enable_seqscan = off;
EXPLAIN ANALYZE
SELECT * FROM person WHERE UPPER(name) = 'ANNA';

DROP INDEX IF EXISTS idx_person_order_multi;
CREATE INDEX idx_person_order_multi ON person_order(person_id, menu_id, order_date);

SET enable_seqscan = off;
EXPLAIN ANALYZE
SELECT person_id, menu_id, order_date
FROM person_order
WHERE person_id = 8 AND menu_id = 19;

DROP INDEX IF EXISTS idx_menu_unique;

CREATE UNIQUE INDEX idx_menu_unique ON menu(pizzeria_id, pizza_name);

SET enable_seqscan = off;
EXPLAIN ANALYZE
SELECT *
FROM menu
WHERE pizzeria_id = 1
  AND pizza_name = 'sausage pizza';

DROP INDEX IF EXISTS idx_person_order_order_date;

CREATE UNIQUE INDEX idx_person_order_order_date
ON person_order(person_id, menu_id)
WHERE order_date = '2022-01-01';

SET enable_seqscan = off;

EXPLAIN ANALYZE
SELECT person_id, menu_id
FROM person_order
WHERE order_date = '2022-01-01'
  AND person_id = 2;

DROP INDEX IF EXISTS idx_1;

CREATE INDEX idx_1 ON pizzeria(id, rating);

SET enable_seqscan = off;
EXPLAIN ANALYZE
SELECT m.pizza_name AS pizza_name,
       max(rating) OVER (
         PARTITION BY rating
         ORDER BY rating
         ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
       ) AS k
FROM menu m
INNER JOIN pizzeria pz ON m.pizzeria_id = pz.id
ORDER BY 1, 2;
